### Fetching data with useEffect and cleanup (manual)

Source: https://react.dev/reference/react/useEffect

Shows a basic data fetching pattern using useEffect with an `ignore` flag to prevent race conditions. The component fetches a bio whenever the selected person changes, clearing the previous bio and ignoring stale responses.

```jsx
import { useState, useEffect } from 'react';
import { fetchBio } from './api.js';

export default function Page() {
  const [person, setPerson] = useState('Alice');
  const [bio, setBio] = useState(null);

  useEffect(() => {
    let ignore = false;
    setBio(null);
    fetchBio(person).then(result => {
      if (!ignore) {
        setBio(result);
      }
    });
    return () => {
      ignore = true;
    };
  }, [person]);

  // ...
```

