### Text field (string) - useState example

Source: https://react.dev/blog/2023/03/16/introducing-react-dev

A React component using useState to hold a string. Typing in the input updates the state and displays the current text below.

```js
import { useState } from 'react';

export default function MyInput() {
  const [text, setText] = useState('hello');

  function handleChange(e) {
    setText(e.target.value);
  }

  return (
    <>
      <input value={text} onChange={handleChange} />
      <p>You typed: {text}</p>
      <button onClick={() => setText('hello')}>
        Reset
      </button>
    </>
  );
}
```
